import {
  standardImage,
  links,
  basicSingleLink,
} from  '#partials'
import { BiListPlus } from 'react-icons/bi'
import { title, text, longerText } from '../shared'

const thumbnails = {
  name: 'list',
  title: 'Thumbnails',
  type: 'array',
  options: {
    collapsable: true,
  },
  of: [
    {
      name: 'item',
      title: 'Item',
      type: 'object',
      fields: [title, longerText, basicSingleLink, standardImage()],
      preview: {
        select: {
          heading: 'title',
          text: 'text',
          image: 'image',
        },
        prepare(selection) {
          const { heading, text, image } = selection
          return {
            title: heading || text,
            media: image || BiListPlus,
          }
        },
      },
    },
  ],
}

const imageThumbnails = {
  name: 'list',
  title: 'Thumbnails',
  type: 'array',
  options: {
    collapsable: true,
  },
  of: [
    {
      name: 'item',
      title: 'Item',
      type: 'object',
      fields: [title, basicSingleLink, standardImage()],
      preview: {
        select: {
          heading: 'title',
          image: 'image',
        },
        prepare(selection) {
          const { heading, image } = selection
          return {
            title: heading,
            media: image || BiListPlus,
          }
        },
      },
    },
  ],
}

const portfolio06Slides = {
  name: 'list',
  title: 'Thumbnails',
  type: 'array',
  options: {
    collapsable: true,
  },
  of: [standardImage()],
}

export { thumbnails, imageThumbnails, portfolio06Slides }
